ALTER TABLE users ADD COLUMN IF NOT EXISTS org_id uuid, ADD COLUMN IF NOT EXISTS role varchar(50) DEFAULT 'user', ADD COLUMN IF NOT EXISTS first_name varchar(100), ADD COLUMN IF NOT EXISTS last_name varchar(100), ADD COLUMN IF NOT EXISTS created_at timestamp with time zone DEFAULT now(), ADD COLUMN IF NOT EXISTS updated_at timestamp with time zone, ADD COLUMN IF NOT EXISTS mfa_enabled boolean DEFAULT false, ADD COLUMN IF NOT EXISTS mfa_secret varchar(255), ADD COLUMN IF NOT EXISTS failed_login_attempts integer DEFAULT 0, ADD COLUMN IF NOT EXISTS locked_until timestamp with time zone;
